import{_ as t,o as s,c as r,a5 as o}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse('{"title":"Serveur MCP Vendora — besoin, expérience et plan (planifié, pas commencé)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/mcp-vendora.md","filePath":"generated/architecture/mcp-vendora.md","lastUpdated":null}'),a={name:"architecture/mcp-vendora.md"};function n(d,e,i,c,l,u){return s(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="serveur-mcp-vendora-—-besoin-experience-et-plan-planifie-pas-commence" tabindex="-1">Serveur MCP Vendora — besoin, expérience et plan (planifié, pas commencé) <a class="header-anchor" href="#serveur-mcp-vendora-—-besoin-experience-et-plan-planifie-pas-commence" aria-label="Permalink to &quot;Serveur MCP Vendora — besoin, expérience et plan (planifié, pas commencé)&quot;">​</a></h1><blockquote><p><strong>Statut : à faire plus tard — besoin révisé le 11/11/2026</strong> (premier plan du 08/11). Rien n&#39;est encore développé. Ce document décrit <strong>à qui ça sert, ce qu&#39;on peut demander, comment on s&#39;en sert</strong>, puis l&#39;architecture et les lots. Mode d&#39;emploi côté commerçant : <a href="/VendoraSystem-docs/architecture/mcp-guide">guide d&#39;utilisation (brouillon)</a>. Suivi : <a href="/VendoraSystem-docs/suivi/journal">TRACKING › MCP Vendora</a> et cartes « MCP » du tableau Trello (M0 → M4, U1 → U6).</p></blockquote><h2 id="_1-en-une-phrase" tabindex="-1">1. En une phrase <a class="header-anchor" href="#_1-en-une-phrase" aria-label="Permalink to &quot;1. En une phrase&quot;">​</a></h2><p><strong>Le commerçant parle à l&#39;assistant qu&#39;il utilise déjà (Claude, ChatGPT…) et obtient des réponses justes sur son commerce</strong> — « Comment s&#39;est passée ma journée ? », « Que dois-je commander ? », « Pourquoi ma marge baisse ? » — depuis son téléphone, sans ouvrir le back-office, sans rien installer, et en pouvant couper l&#39;accès d&#39;un clic.</p><p><strong>MCP (Model Context Protocol)</strong> est le protocole ouvert qui rend cela possible : un serveur déclare des <strong>outils</strong> (nom, description, paramètres) ; l&#39;assistant décide seul quand les appeler et rédige la réponse à partir du résultat. C&#39;est aussi le lot <strong>A8</strong> de l&#39;<a href="/VendoraSystem-docs/commercial/etude-gaas">étude GaaS</a> : le même registre d&#39;outils sert nos futurs agents et l&#39;assistant du commerçant.</p><h2 id="_2-pour-qui-pour-quoi" tabindex="-1">2. Pour qui, pour quoi <a class="header-anchor" href="#_2-pour-qui-pour-quoi" aria-label="Permalink to &quot;2. Pour qui, pour quoi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Qui</th><th>Sa situation</th><th>Ce qu&#39;il attend</th><th>Où il l&#39;utilise</th></tr></thead><tbody><tr><td><strong>Gérant / propriétaire</strong> (restaurant, boulangerie, épicerie, boutique)</td><td>Le soir ou entre deux services, pas le temps d&#39;ouvrir cinq rapports</td><td>Un bilan clair, les anomalies, quoi faire demain</td><td>Application Claude ou ChatGPT <strong>sur son téléphone</strong></td></tr><tr><td><strong>Propriétaire de plusieurs magasins</strong></td><td>Veut comparer sans exporter de tableaux</td><td>Classement des magasins, celui qui décroche et pourquoi</td><td>Téléphone ou ordinateur</td></tr><tr><td><strong>Responsable des achats / chef de cuisine</strong></td><td>Commande à l&#39;instinct, ruptures et pertes</td><td>Liste de réassort par fournisseur, dérive du food cost</td><td>Ordinateur du bureau</td></tr><tr><td><strong>Comptable, contrôleur de gestion</strong></td><td>Prépare les clôtures</td><td>TVA du jour, écarts de caisse, clôtures manquantes, lien vers les exports</td><td>Ordinateur</td></tr><tr><td><strong>Intégrateur, développeur partenaire</strong></td><td>Automatise pour un client</td><td>Outils stables, clé limitée, documentation</td><td>Claude Code, scripts</td></tr></tbody></table><p><strong>Le besoin n&#39;est pas « exposer l&#39;API à une IA »</strong> : c&#39;est faire gagner du temps de lecture et de décision à quelqu&#39;un qui n&#39;est pas technique. Tout le plan en découle : connexion sans copier de clé, outils pensés par <strong>question</strong> (pas par route), chiffres calculés par Vendora (jamais par le modèle), réponses qui disent leur période et leur fraîcheur, et un lien pour aller vérifier dans le back-office.</p><h2 id="_3-ce-que-le-commercant-peut-demander-v1-lecture-seule" tabindex="-1">3. Ce que le commerçant peut demander (v1, lecture seule) <a class="header-anchor" href="#_3-ce-que-le-commercant-peut-demander-v1-lecture-seule" aria-label="Permalink to &quot;3. Ce que le commerçant peut demander (v1, lecture seule)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Priorité</th><th>Question type</th><th>Ce que Vendora renvoie</th><th>Outil</th></tr></thead><tbody><tr><td>1</td><td>« Comment s&#39;est passée ma journée / ma semaine ? »</td><td>Chiffre d&#39;affaires, nombre de tickets, ticket moyen, <strong>écart avec la période précédente équivalente</strong>, heures de pointe, moyens de paiement</td><td><code>sales_summary</code></td></tr><tr><td>1</td><td>« Qu&#39;est-ce qui marche, qu&#39;est-ce qui ne se vend plus ? »</td><td>Meilleures ventes, produits en baisse, produits dormants</td><td><code>top_products</code></td></tr><tr><td>1</td><td>« Que dois-je commander cette semaine ? »</td><td>Produits sous le seuil ou bientôt en rupture au rythme actuel, déjà en commande ou non, regroupés par fournisseur</td><td><code>reorder_suggestions</code></td></tr><tr><td>1</td><td>« Pourquoi ma marge baisse ? »</td><td>Marge par produit et par catégorie, hausses de prix d&#39;achat, dérive du food cost, poids des remises et des pertes</td><td><code>margin_analysis</code></td></tr><tr><td>2</td><td>« Ma caisse est-elle juste ? »</td><td>Sessions ouvertes, écarts de comptage, Z du jour, annulations et remises, validations du manager</td><td><code>cash_control</code></td></tr><tr><td>2</td><td>« Est-ce que tout marche en magasin ? »</td><td>Appareils hors ligne, synchronisation en retard, bornes</td><td><code>devices_health</code></td></tr><tr><td>2</td><td>« Où en sont mes achats ? »</td><td>Bons en cours, réceptions attendues, factures à échéance, soldes fournisseurs</td><td><code>purchasing_status</code></td></tr><tr><td>2</td><td>« Quel magasin décroche ? »</td><td>Comparaison des magasins sur la même période</td><td><code>compare_stores</code></td></tr><tr><td>2</td><td>« Combien vaut mon stock ? Qu&#39;est-ce qui va périmer ? »</td><td>Valeur, ruptures, pertes, lots proches de la date limite</td><td><code>stock_status</code></td></tr><tr><td>3</td><td>« Combien coûte le croissant, combien j&#39;en ai ? »</td><td>Fiche courte d&#39;un produit trouvé par son nom, même approximatif</td><td><code>find_product</code></td></tr><tr><td>3</td><td>« Comment fait-on un inventaire dans Vendora ? »</td><td>Extrait de la page d&#39;aide et son lien</td><td><code>vendora_help</code></td></tr><tr><td>option</td><td>« Y a-t-il des alertes anti-fraude ? »</td><td>Alertes ouvertes (portée sensible, à accorder exprès)</td><td><code>fraud_alerts</code></td></tr></tbody></table><p>Hors v1 : toute écriture (lot M4, par propositions validées), les données nominatives des clients et des salariés (agrégats seulement, voir § 9), le paiement, le fiscal en écriture.</p><h2 id="_4-comment-il-s-en-sert" tabindex="-1">4. Comment il s&#39;en sert <a class="header-anchor" href="#_4-comment-il-s-en-sert" aria-label="Permalink to &quot;4. Comment il s&#39;en sert&quot;">​</a></h2><p>Détail pas à pas : <a href="/VendoraSystem-docs/architecture/mcp-guide">guide d&#39;utilisation</a>. En résumé, trois parcours :</p><ol><li><strong>Commerçant, « en un clic »</strong> (parcours principal) : dans Claude ou ChatGPT, il ajoute le connecteur Vendora (une adresse <code>https://…/mcp</code>, ou plus tard l&#39;annuaire des connecteurs), <strong>se connecte avec son compte Vendora</strong>, choisit les magasins et les familles de données qu&#39;il autorise, et pose sa première question. Aucune clé à copier, fonctionne sur téléphone. Demande OAuth (lot M3).</li><li><strong>Intégrateur, développeur</strong> : il crée une clé « Assistant IA » au back-office et la donne à Claude Code ou à son script (en-tête <code>X-API-Key</code>). Disponible dès M1.</li><li><strong>Essayer sans compte</strong> : un commerce de démonstration public, pour voir ce que ça donne avant de connecter ses vraies données (lot U5).</li></ol><p>Le back-office garde la main : page <strong>Réglages › Assistant IA</strong> avec les assistants connectés, <strong>ce qu&#39;ils ont consulté</strong> en clair (« a lu les ventes du 10/11 de Petit Bistrot »), le retrait d&#39;un accès et l&#39;arrêt d&#39;urgence.</p><h2 id="_5-principes-d-experience" tabindex="-1">5. Principes d&#39;expérience <a class="header-anchor" href="#_5-principes-d-experience" aria-label="Permalink to &quot;5. Principes d&#39;expérience&quot;">​</a></h2><p>Un modèle de langage choisit les outils d&#39;après leur description et rédige d&#39;après leur résultat : <strong>la description et la forme du résultat sont l&#39;interface</strong>. Dix règles, à tenir sur chaque outil.</p><ol><li><strong>Un outil = une question du commerçant</strong>, pas une route de l&#39;API. Une douzaine d&#39;outils au plus ; un modèle choisit mal parmi cinquante.</li><li><strong>Vendora calcule, le modèle raconte.</strong> Totaux, écarts, pourcentages, classements et comparaisons arrivent déjà calculés. Le modèle ne fait jamais d&#39;addition sur une liste.</li><li><strong>Les périodes se disent en mots.</strong> Paramètre <code>period</code> (<code>today</code>, <code>yesterday</code>, <code>this_week</code>, <code>last_week</code>, <code>this_month</code>, <code>last_month</code>, <code>last_7_days</code>, <code>last_30_days</code>, ou <code>from</code> / <code>to</code>) résolu <strong>dans le fuseau du magasin</strong>. La réponse rappelle la période retenue (« du lundi 2 au dimanche 8 novembre »).</li><li><strong>Les noms suffisent.</strong> Magasin et produit acceptés par leur nom, même approximatif ; s&#39;il y a doute, l&#39;outil renvoie les candidats au lieu de deviner. Un seul magasin : le paramètre est facultatif.</li><li><strong>Chaque montant est prêt à citer</strong> : unités mineures, devise <strong>et</strong> texte formaté selon la langue du commerce (« 1 234,50 € »).</li><li><strong>Chaque réponse dit sa fraîcheur</strong> : <code>dataFreshAt</code> ; au-delà de 15 minutes, ou si une caisse n&#39;a pas synchronisé, un avertissement explicite que l&#39;assistant doit répéter.</li><li><strong>Court par défaut</strong> : dix lignes au plus, un résumé en une phrase (<code>summary</code>), le détail sur demande (<code>limit</code>, <code>detail</code>). Les réponses longues coûtent cher et noient le modèle.</li><li><strong>Une suite à chaque réponse</strong> : lien direct vers l&#39;écran du back-office qui montre le même chiffre, et une ou deux questions de suite suggérées.</li><li><strong>Des erreurs qui disent quoi faire</strong>, en clair : « Cet accès ne couvre pas le magasin Lac 2 ; magasins autorisés : Centre, Marsa. Le propriétaire peut l&#39;ajouter dans Réglages › Assistant IA. »</li><li><strong>Ne jamais laisser inventer</strong> : quand la donnée n&#39;existe pas (module non activé, période sans vente), l&#39;outil le dit ; il ne renvoie ni zéro trompeur ni liste vide muette.</li></ol><p>Chaque outil porte un <strong>titre lisible</strong> et l&#39;annotation <strong>lecture seule</strong> (<code>readOnlyHint</code>) : l&#39;assistant peut alors l&#39;appeler sans redemander la permission à chaque fois, et c&#39;est exigé par l&#39;annuaire des connecteurs de Claude.</p><h2 id="_6-catalogue-d-outils-v1" tabindex="-1">6. Catalogue d&#39;outils (v1) <a class="header-anchor" href="#_6-catalogue-d-outils-v1" aria-label="Permalink to &quot;6. Catalogue d&#39;outils (v1)&quot;">​</a></h2><p>Paramètres communs : <code>store</code> (nom ou identifiant, facultatif), <code>period</code> ou <code>from</code> / <code>to</code>, <code>compare_to</code> (<code>previous_period</code> par défaut, <code>same_period_last_year</code>, <code>none</code>), <code>limit</code>. Résultat commun : <code>summary</code>, <code>period</code> (résolue, avec fuseau et libellé), <code>store</code>, les chiffres, <code>dataFreshAt</code>, <code>warnings</code>, <code>links</code> (back-office), <code>nextQuestions</code>. Résultat en texte <strong>et</strong> en contenu structuré avec schéma de sortie (<code>structuredContent</code>, <code>outputSchema</code>).</p><table tabindex="0"><thead><tr><th>Outil</th><th>Titre affiché</th><th>Données de l&#39;API publique</th></tr></thead><tbody><tr><td><code>list_stores</code></td><td>Mes magasins</td><td><code>GET /stores</code> (ceux que l&#39;accès autorise)</td></tr><tr><td><code>sales_summary</code></td><td>Bilan des ventes</td><td>rapports de ventes, tableau de bord, « En direct »</td></tr><tr><td><code>top_products</code></td><td>Produits qui marchent, produits dormants</td><td>rapports de ventes, stock dormant</td></tr><tr><td><code>margin_analysis</code></td><td>Marges et food cost</td><td>rapport des marges, historique des prix d&#39;achat, food cost</td></tr><tr><td><code>stock_status</code></td><td>État du stock</td><td>alertes de stock, valorisation, pertes, lots et dates limites</td></tr><tr><td><code>reorder_suggestions</code></td><td>Quoi commander</td><td>alertes de stock, rotation, bons de commande en cours</td></tr><tr><td><code>cash_control</code></td><td>Caisse et clôtures</td><td>sessions, rapports Z, validations manager</td></tr><tr><td><code>purchasing_status</code></td><td>Achats et fournisseurs</td><td>bons de commande, réceptions, échéances, soldes</td></tr><tr><td><code>devices_health</code></td><td>État des appareils</td><td>parc d&#39;appareils, signaux de santé</td></tr><tr><td><code>compare_stores</code></td><td>Comparer mes magasins</td><td>comparaison des magasins</td></tr><tr><td><code>find_product</code></td><td>Chercher un produit</td><td>catalogue, recherche</td></tr><tr><td><code>vendora_help</code></td><td>Aide Vendora</td><td>index du <a href="https://vendora-aide.onrender.com" target="_blank" rel="noreferrer">centre d&#39;aide</a> (FR / EN / AR)</td></tr><tr><td><code>fraud_alerts</code> (option)</td><td>Alertes anti-fraude</td><td>alertes, portée dédiée</td></tr></tbody></table><p>Noms techniques en anglais (stables, attendus par les annuaires), titres et réponses dans la langue du commerce — décision 5 ci-dessous. Quand un outil demande plusieurs appels (<code>reorder_suggestions</code>, <code>margin_analysis</code>), on ajoute une <strong>route d&#39;agrégation à l&#39;API publique</strong> plutôt que de multiplier les allers-retours : elle sert aussi le back-office et nos agents.</p><p><strong>Prompts prêts</strong> (menu de l&#39;assistant) : « Bilan de ma journée », « Que commander cette semaine ? », « Pourquoi ma marge baisse ? », « Contrôle de caisse du soir », « Point hebdomadaire de mes magasins ».</p><h2 id="_7-architecture" tabindex="-1">7. Architecture <a class="header-anchor" href="#_7-architecture" aria-label="Permalink to &quot;7. Architecture&quot;">​</a></h2><ul><li><strong>Service séparé <code>mcp/</code></strong> dans le monorepo, <strong>client de l&#39;<a href="/VendoraSystem-docs/architecture/api-publique">API publique</a></strong> comme le back-office : jamais d&#39;accès direct à la base, jamais le rôle <code>pos_platform</code> ; les règles métier restent dans le serveur.</li><li><strong>HTTP distant d&#39;abord</strong> (<code>https://mcp.&lt;domaine&gt;/mcp</code>, transport « Streamable HTTP ») : c&#39;est ce que demandent claude.ai, les applications Claude (ordinateur, téléphone), Claude Code et ChatGPT. <strong>stdio</strong> reste possible pour un intégrateur, sans être le parcours du commerçant.</li><li><strong>Sans état, comme le protocole lui-même</strong> : la révision <strong>2026-07-28</strong> de MCP supprime les sessions et la poignée de main d&#39;initialisation ; chaque requête porte sa version et ses capacités, le serveur expose <code>server/discover</code>, chaque résultat porte <code>resultType</code>, les listes portent <code>ttlMs</code> / <code>cacheScope</code> et un ordre stable. Notre choix « sans état » du 08/11 est donc la norme. Le SDK doit aussi parler aux clients restés à la révision 2025-11-25.</li><li><strong>Deux façons de s&#39;authentifier</strong> : clé « Assistant IA » dans un en-tête (intégrateurs, M0 / M1) et <strong>OAuth 2.1</strong> (commerçants, M3). Jamais de jeton dans l&#39;URL.</li><li><strong>OAuth tel que Claude l&#39;attend</strong> (documentation des connecteurs, 11/11/2026) : réponse <strong>401</strong> avec <code>WWW-Authenticate: Bearer resource_metadata=&quot;…&quot;</code>, métadonnées de ressource protégée (RFC 9728) dont <code>resource</code> égale exactement l&#39;URL du serveur MCP, métadonnées du serveur d&#39;autorisation (RFC 8414), <strong>PKCE S256</strong>, identification du client par <strong>CIMD</strong> (Client ID Metadata Document — l&#39;enregistrement dynamique DCR est déprécié, gardé en repli), redirections <code>https://claude.ai/api/mcp/auth_callback</code> et boucle locale de Claude Code (<code>localhost</code> et <code>127.0.0.1</code>, port ignoré), rotation des jetons de renouvellement, paramètre <code>iss</code> (RFC 9207), points OAuth qui répondent en <strong>moins de 10 secondes</strong>.</li><li><strong>Langage proposé : Kotlin</strong> (SDK MCP officiel, cohérent avec le futur service <code>agents/</code>) — alternative TypeScript (SDK le plus mûr, et le seul à fournir le paquet des cartes visuelles <code>@modelcontextprotocol/ext-apps</code>). À trancher.</li><li><strong>Cartes visuelles</strong> (lot U2) : extension officielle <strong>MCP Apps</strong> — un outil désigne une ressource <code>ui://…</code> (HTML) que l&#39;assistant affiche dans la conversation, dans un cadre isolé ; repli en texte partout ailleurs.</li></ul><h2 id="_8-lots" tabindex="-1">8. Lots <a class="header-anchor" href="#_8-lots" aria-label="Permalink to &quot;8. Lots&quot;">​</a></h2><h3 id="m0-—-prerequis-serveur-≈-1-semaine" tabindex="-1">M0 — Prérequis serveur (≈ 1 semaine) <a class="header-anchor" href="#m0-—-prerequis-serveur-≈-1-semaine" aria-label="Permalink to &quot;M0 — Prérequis serveur (≈ 1 semaine)&quot;">​</a></h3><p>Fait le 11/11/2026 (branche <code>mcp-m0</code>). Référence : <a href="/VendoraSystem-docs/architecture/api-publique">API-PUBLIQUE.md</a> §1, §3, §4, §6 ; spec 01 §6 ; spec 17 RG-PLAT-58 / 59.</p><ul><li>[x] Portées fines sur les clés d&#39;API : <strong>16 portées de lecture</strong> (<code>stores</code>, <code>catalog</code>, <code>sales</code>, <code>reports</code>, <code>inventory</code>, <code>purchases</code>, <code>devices</code>, <code>customers</code>, <code>fiscal</code>, <code>accounting</code>, <code>fraud</code>, <code>team</code>, <code>audit</code>, <code>settings</code>, <code>webhooks</code>, <code>account</code> — toutes en <code>:read</code>), READ / WRITE conservés à l&#39;identique. Classement route → portée <strong>fermé par défaut</strong> (<code>ApiKeyScopeRegistry</code>), un test échoue si une route publique de lecture n&#39;est pas classée. 403 <code>API_KEY_SCOPE</code> avec <code>requiredScope</code> et un message qui nomme la portée. <em>Pas fait : portées fines d&#39;écriture (hors lot, M4).</em></li><li>[x] Restriction d&#39;une clé (à portées fines) à un ou plusieurs magasins : 404 <code>STORE_NOT_ALLOWED</code> sur un autre magasin, listes et agrégats filtrés, routes du commerce entier refusées (403 <code>API_KEY_STORE_RESTRICTED</code>). Double barrière : contrôle de la route <strong>et</strong> politique PostgreSQL <code>store_scope</code>. Un test par contournement envisagé (agrégat, export, identifiant deviné, paramètre <code>storeId</code>).</li><li>[x] Type de clé « Assistant IA » (<code>kind = AGENT</code>) : lecture seule, préréglage <code>stores</code>, <code>catalog</code>, <code>sales</code>, <code>reports</code>, <code>inventory</code>, <code>purchases</code>, <code>devices</code> — <strong>sans <code>customers:read</code></strong> —, 120 requêtes par minute, expiration 90 jours par défaut (365 au plus).</li><li>[x] Acteur <code>AGENT</code> : journal <strong>dédié</strong> <code>agent_activity</code> (et non <code>audit_log</code>, réservé aux modifications), une ligne par clé, jour, lecture, magasin et période, avec compteur. Libellé lisible par code stable + paramètres, en français côté serveur et FR / EN / AR côté back-office. Route <code>GET /api/v1/agent-activity</code> prête pour la page du lot M2 (<strong>la page n&#39;est pas faite</strong>, comme prévu).</li><li>[x] Droit <code>MCP_ACCESS</code> dans les formules (console, actif dans toutes les formules existantes) ; arrêt d&#39;urgence par commerce (back-office, propriétaire) et global (console, ADMIN, motif obligatoire). Effet <strong>dès la requête suivante</strong>, sans cache (mesuré : refus 3 ms après la réponse de la bascule).</li><li>[x] Tests d&#39;intégration (<code>AgentAccessM0IntegrationTest</code>, <code>ApiKeyScopeRegistryTest</code>) ; <code>API-PUBLIQUE.md</code>, OpenAPI, specs 01, 13 et 17, centre d&#39;aide (page Clés d&#39;API, FR / EN / AR) à jour.</li></ul><p><strong>À savoir pour M1</strong> : la clé se présente par <code>Authorization: Bearer vd_live_…</code> ou <code>X-API-Key</code> ; <code>GET /api/v1/api-keys/me</code> donne ses portées et ses magasins (<code>storeIds</code>, <code>null</code> = tous) — à lire au démarrage pour n&#39;exposer que les outils utilisables. Les erreurs portent <code>error</code> (message relayable tel quel) et <code>code</code> ; <code>Retry-After</code> sur 429. Les routes d&#39;agrégation à ajouter en M1 doivent être <strong>classées</strong> dans <code>ApiKeyScopeRegistry</code> (sinon elles restent fermées et le test de classement échoue).</p><h3 id="m1-—-serveur-mcp-en-lecture-seule-≈-1-5-semaine" tabindex="-1">M1 — Serveur MCP en lecture seule (≈ 1,5 semaine) <a class="header-anchor" href="#m1-—-serveur-mcp-en-lecture-seule-≈-1-5-semaine" aria-label="Permalink to &quot;M1 — Serveur MCP en lecture seule (≈ 1,5 semaine)&quot;">​</a></h3><ul><li>[ ] Service <code>mcp/</code>, HTTP distant (révision 2026-07-28, compatible 2025-11-25) et stdio ; clé « Assistant IA ».</li><li>[ ] Les outils du § 6 selon les dix règles du § 5 ; titre et annotation lecture seule sur chacun ; sortie structurée.</li><li>[ ] Routes d&#39;agrégation de l&#39;API publique pour le réassort et l&#39;analyse de marge.</li><li>[ ] Prompts prêts ; balisage des textes libres comme données (§ 9).</li><li>[ ] Tests par outil contre un faux serveur, MCP Inspector, <strong>preuve réelle</strong> avec Claude Code sur le serveur de dev et le commerce de démo ; premier passage du jeu de questions de référence (U1).</li></ul><h3 id="m3-—-connexion-oauth-2-1-≈-1-5-semaine-—-recommande-avant-m2" tabindex="-1">M3 — Connexion OAuth 2.1 (≈ 1,5 semaine) — <strong>recommandé avant M2</strong> <a class="header-anchor" href="#m3-—-connexion-oauth-2-1-≈-1-5-semaine-—-recommande-avant-m2" aria-label="Permalink to &quot;M3 — Connexion OAuth 2.1 (≈ 1,5 semaine) — **recommandé avant M2**&quot;">​</a></h3><ul><li>[ ] Serveur d&#39;autorisation sur le serveur Vendora (comptes du back-office), conforme au § 7.</li><li>[ ] Écran de consentement FR / EN / AR en langage simple : quel assistant, quels magasins, quelles familles de données, lecture seule ; modifiable, refus possible.</li><li>[ ] Jetons courts liés à l&#39;utilisateur, aux magasins et aux portées ; mêmes règles que les clés (audit <code>AGENT</code>, arrêt d&#39;urgence, <code>MCP_ACCESS</code>) ; révocation au back-office.</li><li>[ ] Preuve réelle : connecteur ajouté dans Claude sur le staging, depuis un téléphone.</li></ul><h3 id="m2-—-page-«-assistant-ia-»-tutoriel-hebergement-≈-1-semaine" tabindex="-1">M2 — Page « Assistant IA », tutoriel, hébergement (≈ 1 semaine) <a class="header-anchor" href="#m2-—-page-«-assistant-ia-»-tutoriel-hebergement-≈-1-semaine" aria-label="Permalink to &quot;M2 — Page « Assistant IA », tutoriel, hébergement (≈ 1 semaine)&quot;">​</a></h3><ul><li>[ ] Back-office › Réglages › <strong>Assistant IA</strong> : « Connecter Claude », « Connecter ChatGPT » (adresse à copier, QR pour le téléphone, étapes illustrées), bouton <strong>Tester la connexion</strong>, assistants connectés, clés pour intégrateurs, <strong>activité lisible</strong>, retrait d&#39;un accès, arrêt d&#39;urgence, questions pour bien commencer.</li><li>[ ] Centre d&#39;aide : « Brancher votre assistant IA » à partir du <a href="/VendoraSystem-docs/architecture/mcp-guide">guide</a>, FR / EN / AR.</li><li>[ ] Hébergement de staging <code>vendora-mcp-staging</code> — <strong>sans mise en veille</strong> : un service qui dort ne tient pas les 10 secondes laissées aux points OAuth.</li><li>[ ] Spec <strong>18-mcp</strong>, site (fonctionnalités, vitrine), README.</li></ul><h3 id="experience-u1-→-u6" tabindex="-1">Expérience (U1 → U6) <a class="header-anchor" href="#experience-u1-→-u6" aria-label="Permalink to &quot;Expérience (U1 → U6)&quot;">​</a></h3><ul><li>[ ] <strong>U1 — Jeu de questions de référence</strong> (≈ 4 jours) : 40 questions réelles et leurs réponses attendues sur le commerce de démo, rejouées à chaque changement d&#39;outil ; journal des questions restées sans réponse.</li><li>[ ] <strong>U2 — Cartes visuelles dans la conversation</strong> (≈ 1 semaine) : bilan du jour, réassort, comparaison des magasins en MCP Apps, repli en texte.</li><li>[ ] <strong>U3 — Bibliothèque de questions et routines par métier</strong> (≈ 3 jours) : restaurant, boulangerie, épicerie, boutique ; prompts, page d&#39;aide, exemples au back-office, bilans programmés.</li><li>[ ] <strong>U4 — Aide Vendora et liens directs</strong> (≈ 3 jours) : outil <code>vendora_help</code>, liens vers l&#39;écran du back-office dans chaque réponse.</li><li>[ ] <strong>U5 — Commerce de démonstration public</strong> (≈ 3 jours) : serveur de démo sans compte, données fictives, bouton « Essayer avec Claude » sur la vitrine.</li><li>[ ] <strong>U6 — Annuaires Claude et ChatGPT</strong> (≈ 4 jours + délai de revue) : fiche, politique de confidentialité, documentation publique, compte de test, captures.</li></ul><h3 id="m4-—-ecriture-encadree-apres-le-lot-gaas-a2" tabindex="-1">M4 — Écriture encadrée (après le lot GaaS A2) <a class="header-anchor" href="#m4-—-ecriture-encadree-apres-le-lot-gaas-a2" aria-label="Permalink to &quot;M4 — Écriture encadrée (après le lot GaaS A2)&quot;">​</a></h3><ul><li>[ ] Aucune écriture directe : les outils d&#39;écriture <strong>créent des propositions</strong> (<code>agent_proposals</code>) — bon de commande brouillon, changement de prix, acquittement d&#39;alerte — validées par le gérant (back-office, app, PIN manager). Annotations d&#39;écriture sur ces outils ; l&#39;assistant redemande alors la permission.</li></ul><h2 id="_9-garde-fous-des-m1" tabindex="-1">9. Garde-fous (dès M1) <a class="header-anchor" href="#_9-garde-fous-des-m1" aria-label="Permalink to &quot;9. Garde-fous (dès M1)&quot;">​</a></h2><ul><li><strong>Lecture seule</strong> tant que M4 n&#39;existe pas ; paiement, fiscal en écriture, PIN, clés et délégations hors d&#39;atteinte (comme l&#39;API publique).</li><li><strong>Données personnelles</strong> : clients et salariés en agrégats ou pseudonymisés ; noms et coordonnées seulement avec la portée <code>customers:read</code>, décochée par défaut et expliquée à l&#39;écran de consentement.</li><li><strong>Injection de consignes</strong> : noms de produits, notes fournisseurs, messages de clients sont des <strong>données</strong>, jamais des instructions ; les réponses des outils les balisent comme telles.</li><li><strong>Le commerçant choisit où vont ses données</strong> : Vendora ne les transmet qu&#39;à l&#39;assistant qu&#39;il a lui-même connecté ; l&#39;écran de consentement et le guide le disent, avec un renvoi aux conditions de l&#39;assistant.</li><li>Débit limité par accès, audit de chaque appel, révocation immédiate, vérification de l&#39;en-tête <code>Origin</code>.</li></ul><h2 id="_10-mesures-de-succes" tabindex="-1">10. Mesures de succès <a class="header-anchor" href="#_10-mesures-de-succes" aria-label="Permalink to &quot;10. Mesures de succès&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mesure</th><th>Cible</th></tr></thead><tbody><tr><td>Temps entre « Connecter » et la première réponse</td><td>moins de 2 minutes (médiane)</td></tr><tr><td>Questions de référence correctes (bon outil, bon chiffre, bonne période)</td><td>90 % au moins, <strong>aucun chiffre inventé</strong></td></tr><tr><td>Temps de réponse d&#39;un outil</td><td>moins de 2 secondes (95e centile)</td></tr><tr><td>Commerces avec un assistant connecté 30 jours après l&#39;ouverture</td><td>à suivre (console)</td></tr><tr><td>Commerces qui posent au moins une question par semaine</td><td>à suivre</td></tr><tr><td>Questions sans réponse les plus fréquentes</td><td>revues chaque mois, alimentent les outils</td></tr></tbody></table><h2 id="_11-effort-et-ordre-recommande" tabindex="-1">11. Effort et ordre recommandé <a class="header-anchor" href="#_11-effort-et-ordre-recommande" aria-label="Permalink to &quot;11. Effort et ordre recommandé&quot;">​</a></h2><p><code>M0 → M1 (+ U1) → M3 → M2 (+ U3, U4) → U5 → U2 → U6 → M4</code></p><ul><li><strong>Utilisable par un intégrateur</strong> (clé, Claude Code) : M0 + M1 ≈ 2,5 semaines.</li><li><strong>Utilisable par un commerçant seul, sur son téléphone</strong> : + M3 + M2 ≈ 5 semaines au total.</li><li>Expérience complète (U1 → U6) : ≈ 3,5 semaines de plus, par petits lots indépendants. M4 avec la suite GaaS.</li></ul><h2 id="_12-decisions-a-prendre-avant-de-demarrer" tabindex="-1">12. Décisions à prendre avant de démarrer <a class="header-anchor" href="#_12-decisions-a-prendre-avant-de-demarrer" aria-label="Permalink to &quot;12. Décisions à prendre avant de démarrer&quot;">​</a></h2><ol><li><strong>Langage</strong> : Kotlin (recommandé pour la cohérence) ou TypeScript (recommandé si les cartes visuelles U2 passent en priorité).</li><li><strong>Ordre</strong> : OAuth (M3) <strong>avant</strong> la page du back-office (nouvelle recommandation), ou clé à copier d&#39;abord (plan du 08/11). Raison du changement : sur claude.ai et ses applications, la clé dans un en-tête est en bêta et réservée au propriétaire d&#39;une organisation ; un commerçant sur son téléphone ne peut se connecter que par OAuth.</li><li><strong>Données clients</strong> : exclues de la v1 (recommandé) ou accessibles avec une portée explicite.</li><li><strong>Commercial</strong> : inclus dans toutes les formules (lecture seule) ou réservé à une formule / un add-on.</li><li><strong>Langue des outils</strong> : noms techniques en anglais et titres dans la langue du commerce (recommandé), ou tout en français.</li><li><strong>Domaine</strong> du serveur (<code>mcp.…</code>) et hébergement de production — l&#39;adresse ne doit plus changer une fois les commerçants connectés.</li></ol><h2 id="_13-ce-qui-change-par-rapport-au-plan-du-08-11" tabindex="-1">13. Ce qui change par rapport au plan du 08/11 <a class="header-anchor" href="#_13-ce-qui-change-par-rapport-au-plan-du-08-11" aria-label="Permalink to &quot;13. Ce qui change par rapport au plan du 08/11&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sujet</th><th>Plan du 08/11</th><th>Besoin révisé du 11/11</th></tr></thead><tbody><tr><td>Point de départ</td><td>Exposer l&#39;API en outils</td><td>Les questions du commerçant, par métier</td></tr><tr><td>Connexion</td><td>Clé à copier d&#39;abord, OAuth « peut attendre »</td><td>OAuth avant la page ; la clé pour les intégrateurs</td></tr><tr><td>Transport</td><td>stdio et HTTP à égalité</td><td>HTTP distant d&#39;abord, stdio en option</td></tr><tr><td>Outils</td><td>Une douzaine, calqués sur les rapports</td><td>Par question, périodes en mots, comparaison incluse, erreurs utiles, liens</td></tr><tr><td>Réponses</td><td>Texte et montants formatés</td><td>+ contenu structuré, questions de suite, cartes visuelles (U2)</td></tr><tr><td>Qualité</td><td>Tests par outil</td><td>+ jeu de questions de référence rejoué à chaque changement (U1)</td></tr><tr><td>Découverte</td><td>Tutoriel</td><td>+ commerce de démo public (U5), annuaires (U6), bibliothèque de questions (U3)</td></tr><tr><td>Protocole</td><td>« Sans état » comme choix</td><td>Révision 2026-07-28 : sans état par construction, CIMD, annotations</td></tr></tbody></table><h2 id="_14-sources-consultees-le-11-11-2026" tabindex="-1">14. Sources (consultées le 11/11/2026) <a class="header-anchor" href="#_14-sources-consultees-le-11-11-2026" aria-label="Permalink to &quot;14. Sources (consultées le 11/11/2026)&quot;">​</a></h2><ul><li>Protocole MCP, changements de la révision 2026-07-28 : &lt;<a href="https://modelcontextprotocol.io/specification/2026-07-28/changelog" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28/changelog</a>&gt;</li><li>Connecteurs Claude — authentification : &lt;<a href="https://claude.com/docs/connectors/building/authentication" target="_blank" rel="noreferrer">https://claude.com/docs/connectors/building/authentication</a>&gt;</li><li>Connecteurs Claude — soumission à l&#39;annuaire : &lt;<a href="https://claude.com/docs/connectors/building/submission" target="_blank" rel="noreferrer">https://claude.com/docs/connectors/building/submission</a>&gt;</li><li>Connecteurs Claude — ajouter un connecteur personnalisé : &lt;<a href="https://claude.com/docs/connectors/custom/add-unlisted.md" target="_blank" rel="noreferrer">https://claude.com/docs/connectors/custom/add-unlisted.md</a>&gt;</li><li>MCP Apps (cartes visuelles) : &lt;<a href="https://blog.modelcontextprotocol.io/posts/2026-01-26-mcp-apps/" target="_blank" rel="noreferrer">https://blog.modelcontextprotocol.io/posts/2026-01-26-mcp-apps/</a>&gt;</li><li>ChatGPT — serveurs MCP personnalisés : &lt;<a href="https://help.openai.com/articles/12584461" target="_blank" rel="noreferrer">https://help.openai.com/articles/12584461</a>&gt; et &lt;<a href="https://developers.openai.com/api/docs/guides/custom-mcp-server.md" target="_blank" rel="noreferrer">https://developers.openai.com/api/docs/guides/custom-mcp-server.md</a>&gt; (disponibilité selon les formules : à revérifier au démarrage du lot M3)</li></ul></div>',1)])])}const g=t(a,[["render",n]]);export{m as __pageData,g as default};
